/**
 * Extract `parentSelectMap` into `parentSelect`.
 *
 * ParentSelect value needs to be extracted from parentSelectMap because selected id can share the
 * same parent / grand parent.
 *
 * The importance of `parentSelectMap` becomes even more obvious when parentSelect gets deselected.
 *
 * @since ??
 *
 * @param {Record<string, string[]>} parentSelectMap Parent select map.
 *
 * @returns {Record<string, string>} Parent select.
 *
 * @example
 *
 * ```js
 * // Consider two selected modules with the following parents:
 * // ['section1', 'row1', 'column1', 'module1']
 * // ['section1', 'row1', 'column2', 'module2']
 *
 *
 * // This means extracted `parentSelect` would be:
 * {section1: 'section1', row1: 'row1', column1:
 * 'column1', column2: 'column2', module1: 'module1`, module2: 'module2'}
 * ```
 */
export declare const extractParentSelect: (parentSelectMap: Record<string, string[]>) => Record<string, string>;
